# -*- coding: utf-8 -*-
"""Self-contained workbench replay: measured events and MuJoCo video share one clock."""
import base64
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'results/mujoco'
def case(name,video):
    trace=json.loads((BASE/name/'trace.json').read_text())
    tasks=trace['batches'][0]['tasks']
    starts=[e for e in trace['backend_events'] if e['state']=='start']
    items=[]
    for i,t in enumerate(tasks):
        m=None
        if i<len(starts):
            m=json.loads((BASE/name/'simulation'/starts[i]['action']/'metrics.json').read_text())
        items.append({**t,'metrics':m})
    return {'id':name,'text':trace['text'],'outcome':trace['outcome'],'final':trace['final'],'tasks':items,'events':trace['backend_events'],'video':('data:video/mp4;base64,'+base64.b64encode((BASE/video).read_bytes()).decode()) if video else None}
data=[case('welcome','welcome_sequence.mp4'),case('cancel','cancel/simulation/dance.perform/motion.mp4'),case('failure',None)]
html=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Q1 技能工作台 · MuJoCo 联动回放</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f4f0;color:#263c36;font:15px/1.55 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}button,select,input{font:inherit}button{cursor:pointer}header{height:78px;background:#fff;border-bottom:1px solid #dfe5df;display:flex;align-items:center;justify-content:space-between;padding:0 38px}.brand{font-size:23px;font-weight:750;letter-spacing:-.5px}.brand small{font-size:13px;color:#87948c;margin-left:18px;font-weight:400}.logo{display:inline-grid;place-items:center;background:#2c6553;color:white;width:35px;height:35px;border-radius:10px;font:700 14px monospace;margin-right:10px}.pill{display:inline-flex;align-items:center;gap:7px;border:1px solid #d4e4d9;border-radius:20px;padding:5px 12px;font-size:12px;background:#edf5ef;color:#386d55}.pill:before{content:'';width:6px;height:6px;background:#5a9276;border-radius:50%}.shell{max-width:1560px;padding:25px 30px 20px;margin:auto}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.eyebrow{font-size:11px;letter-spacing:1.6px;color:#839189;font-weight:650}h1{font-size:24px;margin:3px 0;font-weight:700}.switch{display:flex;gap:7px}.switch button{padding:8px 14px;background:transparent;border:1px solid #d3ddd6;border-radius:8px;color:#75867b}.switch button.active{background:#325e4d;color:white;border-color:#325e4d}.grid{display:grid;grid-template-columns:390px minmax(0,1fr);gap:20px;align-items:start}.panel{background:white;border:1px solid #dfe5df;border-radius:14px;overflow:hidden}.left{padding:23px}.sectiontitle{font-weight:700;font-size:15px;display:flex;align-items:center;justify-content:space-between;margin-bottom:13px}.micro{font-size:11px;color:#86938c;font-weight:400}.request{padding:17px 18px;background:#edf3ec;border-radius:2px 12px 12px 12px;font-size:18px;line-height:1.65;min-height:94px;margin-bottom:19px}.flow{font-size:11px;color:#87918c;margin-bottom:21px}.task{border:1px solid #dfe5df;border-radius:10px;margin-bottom:10px;padding:13px 15px;background:#fbfcfa;transition:background .12s}.task.active{background:#eaf4ee;border-color:#6d9b81;box-shadow:inset 3px 0 #437a5d}.task.failed{background:#fcf2eb;border-color:#d6a58a}.task.skipped{opacity:.6}.taskhead{display:flex;align-items:center;justify-content:space-between}.taskname{font-size:16px;font-weight:650}.taskid{font:11px monospace;color:#82948a;margin-right:6px}.badge{font-size:11px;padding:2px 7px;background:#eaf0eb;color:#60806d;border-radius:5px}.active .badge{background:#347051;color:white}.failed .badge{background:#e7c6b4;color:#8a4b30}.code{font:12px/1.7 ui-monospace,SFMono-Regular,monospace;color:#708078;margin-top:6px}.params{font-size:12px;color:#809087;display:flex;justify-content:space-between;margin-top:6px}.result{padding:12px 14px;border-left:3px solid #508669;background:#f5f7f3;font-size:13px;line-height:1.7;min-height:66px}.stack{display:flex;gap:7px;flex-wrap:wrap;margin-top:17px}.stack span{border:1px solid #dfe5df;border-radius:5px;padding:3px 7px;font-size:10px;color:#7e8e84}.simhead{display:flex;justify-content:space-between;align-items:center;padding:15px 21px;border-bottom:1px solid #e6ebe5}.simhead strong{font-size:16px}.simhead .micro{margin-left:10px}.clock{font:14px monospace;color:#4e7561}.viewport{position:relative;background:#fff;height:450px;overflow:hidden;display:grid;place-items:center}video{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.viewtag{position:absolute;top:16px;left:19px;background:#f4f7f2e6;border:1px solid #dbe4dc;border-radius:6px;font-size:11px;padding:5px 9px;color:#698273}.current{position:absolute;bottom:15px;left:19px;right:19px;display:flex;justify-content:space-between;align-items:end;pointer-events:none}.current span{background:#fffE;padding:5px 10px;border-radius:6px;font-size:12px;color:#50715f}.current b{font:12px monospace;color:#74837b;background:#fffE;padding:5px 9px;border-radius:6px}.empty{color:#8d998f;text-align:center;line-height:2}.transport{padding:12px 21px 15px;border-top:1px solid #e7eae5;background:#fcfdfb}.segments{display:flex;gap:3px;height:5px;margin-bottom:10px}.segments span{border-radius:3px;background:#d9e6dc}.segments span:nth-child(2){background:#93b39d}.segments span:nth-child(3){background:#497b62}.controls{display:flex;gap:12px;align-items:center}.controls button{border:1px solid #d4ded6;background:white;color:#3e6851;border-radius:6px;height:32px;min-width:45px;font-size:12px}.controls button#play{background:#315e4d;color:white;border-color:#315e4d;min-width:72px}.controls input{flex:1;accent-color:#487d60;min-width:80px}.controls time{font:12px monospace;color:#758a7d;min-width:105px}.logs{padding:15px 21px 13px}.logtitle{display:flex;justify-content:space-between;align-items:center;font-size:13px;font-weight:650;margin-bottom:8px}.event{display:grid;grid-template-columns:70px 1fr 110px;gap:10px;font-size:12px;padding:5px 0;border-bottom:1px solid #f0f2ed}.event:last-child{border:0}.event time{font:11px monospace;color:#90a092}.event span:last-child{color:#5d826a;text-align:right}.footer{color:#8a978e;font-size:11px;margin-top:14px;display:flex;justify-content:space-between}.hidden{display:none!important}@media(max-width:1000px){.grid{grid-template-columns:1fr}.left{order:2}.shell{padding:18px}.brand small{display:none}} 
</style>
<header><div class="brand"><span class="logo">Q1</span>技能工作台<small>PrimeBuddy × 本地 Qwen3</small></div><span class="pill">MuJoCo · 实验回放</span></header>
<div class="shell"><div class="toolbar"><div><div class="eyebrow">LANGUAGE → SKILLS → MOTION</div><h1>一句话，看见机器人如何执行</h1></div><div class="switch"><button data-case="welcome" class="active">迎宾组合</button><button data-case="cancel">取消舞蹈</button><button data-case="failure">前置失败</button></div></div>
<div class="grid"><aside class="panel left"><div class="sectiontitle">用户指令<span class="micro">本地模型 · Qwen3-4B</span></div><div class="request" id="request"></div><div class="flow">意图判断　→　生成计划　→　校验依赖　→　执行</div><div class="sectiontitle">任务编排<span class="micro" id="taskcount"></span></div><div id="tasks"></div><div class="sectiontitle" style="margin-top:20px">回放状态<span class="micro">由记录计算</span></div><div class="result" id="receipt"></div><div class="stack"><span>RTX 5070 Ti</span><span>MuJoCo 3.3.7</span><span>22 个关节</span><span>PD · 1 kHz</span></div></aside>
<section class="panel"><div class="simhead"><div><strong>Q1 仿真视窗</strong><span class="micro">固定底座 · 正面视角</span></div><span class="clock" id="clock"></span></div><div class="viewport"><video id="video" muted playsinline preload="auto"></video><div id="empty" class="empty hidden">执行器在动作启动前返回失败<br>本案例没有生成运动画面</div><div class="viewtag">实测关节状态 · 25 FPS</div><div class="current"><span id="current"></span><b id="steps"></b></div></div><div class="transport"><div class="segments" id="segments"></div><div class="controls"><button id="play">播放</button><button id="back">− 帧</button><button id="next">+ 帧</button><input id="seek" type="range" min="0" max="1000" value="0" aria-label="回放进度"><time id="time"></time></div></div><div class="logs"><div class="logtitle">执行事件<span class="micro">按仿真时钟同步</span></div><div id="events"></div></div></section></div><div class="footer"><span>本页联动播放真实运行记录，不发送控制命令。画面与状态使用同一仿真时间。</span><span>固定骨盆 / 重力开启 / 机器人碰撞关闭</span></div></div>
<script>
const DATA=__DATA__;
const $=s=>document.querySelector(s),v=$('#video');let chosen=DATA[0],total=4.2,raf;
const labels={'greeting.say':'问候','gesture.wave':'挥手','gesture.heart':'双臂内收','dance.perform':'舞蹈'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function action(t){return t.skill==='gesture'?'gesture.'+t.args.name:t.skill+'.'+t.action}
function simTime(){return chosen.video?Math.min(total,(Math.floor((v.currentTime+1e-7)*25)+1)*.04):0}
function draw(){let t=simTime(),atEnd=chosen.video?(v.ended||v.currentTime>=total-.041):true;let current='等待播放';
 $('#tasks').innerHTML=chosen.tasks.map(task=>{let m=task.metrics,state='等待前置任务',css='';if(m){if(m.status==='failed'){state='执行失败';css='failed'}else if(t>=m.end_sim_s-1e-7){state=m.status==='cancelled'?'已取消':'已完成';css=m.status==='cancelled'?'failed':''}else if(t>=m.start_sim_s){state='执行中';css='active';current=labels[action(task)]}}else if(atEnd){state=chosen.outcome==='cancelled'?'未启动':'已跳过';css='skipped'}return '<div class="task '+css+'" data-task="'+task.id+'"><div class="taskhead"><span class="taskname"><span class="taskid">'+task.id+'</span>'+labels[action(task)]+'</span><span class="badge">'+state+'</span></div><div class="code">'+esc(task.skill+'.'+task.action)+'</div><div class="params"><span>'+esc(JSON.stringify(task.args))+'</span><span>after: '+(task.after.join(', ')||'—')+'</span></div></div>'}).join('');
 $('#request').textContent=chosen.text;$('#taskcount').textContent=chosen.tasks.length+' 个任务';$('#clock').textContent='SIM '+t.toFixed(2)+' s';$('#time').textContent=t.toFixed(2)+' / '+total.toFixed(2)+' s';$('#seek').value=total?v.currentTime/total*1000:0;
 $('#current').textContent=atEnd?(chosen.outcome==='cancelled'?'取消已处理 · 后续任务未启动':chosen.id==='failure'?'动作未执行':'本次任务完成'):current+' · 轨迹执行';$('#steps').textContent=Math.round(t/.001).toLocaleString()+' physics steps';
 $('#receipt').textContent=atEnd?chosen.final:'正在回放「'+current+'」；后续任务等待当前动作完成。';
 let events=chosen.events.filter(e=>e.sim_time<=t+1e-7);$('#events').innerHTML=events.slice(-3).map(e=>'<div class="event"><time>'+e.sim_time.toFixed(2)+' s</time><span>'+esc(e.action)+'</span><span>'+({start:'启动',success:'完成',released:'释放资源',failed:'执行失败',interrupted:'取消中断'}[e.state]||e.state)+'</span></div>').join('');$('#play').textContent=v.paused?'播放':'暂停';
}
function loop(){draw();if(!v.paused)raf=requestAnimationFrame(loop)}
function select(id){v.pause();cancelAnimationFrame(raf);chosen=DATA.find(c=>c.id===id);total=Math.max(0,...chosen.tasks.map(t=>t.metrics?.end_sim_s||0));if(chosen.video){v.src=chosen.video;v.load()}else{v.removeAttribute('src');v.load()}v.classList.toggle('hidden',!chosen.video);$('#empty').classList.toggle('hidden',!!chosen.video);document.querySelectorAll('.controls button,.controls input').forEach(b=>b.disabled=!chosen.video);document.querySelectorAll('[data-case]').forEach(b=>b.classList.toggle('active',b.dataset.case===id));$('#segments').innerHTML=chosen.tasks.map(t=>'<span style="flex:'+(t.metrics?t.metrics.end_sim_s-t.metrics.start_sim_s:1)+'"></span>').join('');draw()}
document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>select(b.dataset.case));$('#play').onclick=()=>{if(v.paused){if(v.ended)v.currentTime=0;v.play().catch(console.error)}else v.pause()};$('#back').onclick=()=>{v.pause();v.currentTime=Math.max(0,v.currentTime-.04)};$('#next').onclick=()=>{v.pause();v.currentTime=Math.min(total-.04,v.currentTime+.04)};$('#seek').oninput=e=>{v.pause();v.currentTime=Math.min(total-.04,total*e.target.value/1000)};v.onplay=loop;v.onpause=draw;v.onseeked=draw;v.onloadeddata=draw;v.onended=draw;v.ontimeupdate=draw;select('welcome');window.workbenchReady=true;
</script></html>'''
(ROOT/'仿真工作台.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')))
print('Built self-contained workbench')
